  const PRODUCTS = DATA.products;

  const SHOW_BARRIERS = false;

  const PAGE_LANG = document.documentElement.lang || "en";

  const DATE_LANG = /^en\b/i.test(PAGE_LANG) ? "en-GB" : PAGE_LANG;

  const tracked = PRODUCTS.filter(p => !p.placeholder)
