      MOZ: "AFRO", MRT: "AFRO", MUS: "AFRO", MWI: "AFRO", MYS: "WPRO", NAM: "AFRO",
      NER: "AFRO", NGA: "AFRO", NIC: "AMRO", NIU: "WPRO", NLD: "EURO", NOR: "EURO",
