      TKM: "EURO", TLS: "SEARO", TON: "WPRO", TTO: "AMRO", TUN: "EMRO", TUR: "EURO",
      TZA: "AFRO", UGA: "AFRO", UKR: "EURO", URY: "AMRO", USA: "AMRO", UZB: "EURO",
      VCT: "AMRO", VEN: "AMRO", VNM: "WPRO", VUT: "WPRO", WSM: "WPRO", YEM: "EMRO",
      ZAF: "AFRO", ZMB: "AFRO", ZWE: "AFRO",
