    wrap.innerHTML = `<div id="mapwrap-gl"></div>
      <div class="map-empty" id="map-empty" hidden></div>
      <span class="map-zoom-lvl" id="mz-lvl" aria-live="polite" hidden></span>
      <ul class="map-country-list" id="map-country-list" aria-label="Pays figurant sur cette carte, liste"></ul>`;

    // ---- MapLibre init (DEV-13 D18/D19 — supersedes D13) -------------------
    // An earlier decision rejected any mapping library ("the first runtime
    // dependency on a page that has none"). Overridden here, deliberately, and
    // for this page only: the pan/zoom, per-site-dot map the feature needs
    // could not be built on the hand-rolled viewBox/SVG renderer it replaced —
    // clustering, projection and hit-testing were all being reinvented badly.
    // That argument does NOT extend to any other page in this repo.
    // (The per-site dots have since been removed — see docs/handoff-remove-study-layers.md
    // — so the dependency now rests on pan/zoom and the sharper 50m basemap alone.)
    const LON0 = -120, LON1 = 155, LAT0 = -40, LAT1 = 42;   // same window build-map-geo.js fits to
    // ZMAX is a LINEAR multiplier (D13's original meaning: "16x magnified").
    // MapLibre's own zoom is exponential (each +1 level doubles the scale),
    // so the map option below must be log2(ZMAX), not ZMAX itself — passing
    // 16 there means a 2^16 = 65536x cap, not 16x (D26: found via the
    // mzLvl readout showing "65536×" and the map collapsing to a single flat
    // colour at that zoom; D13's basemap-detail reasoning was never wrong,
    // it just never reached the map option it was meant to bound).
    const ZMAX = 64;   // D13's basemap-detail reasoning still applies, now against a sharper 50m basemap; 16->64 per D29
    const TOKEN = (name) => getComputedStyle(document.documentElement).getPropertyValue(name).trim();
    let mapColors = {};
    function readMapColors() {
      mapColors = {
        registered: TOKEN("--map-registered") || TOKEN("--map1"),
        guidelines: TOKEN("--map-guidelines") || TOKEN("--map2"),
        mft: TOKEN("--map-mft") || TOKEN("--map3"),
        nodata: TOKEN("--map-nodata"),
        border: TOKEN("--map-border"),
        surface2: TOKEN("--surface-2"),
      };
    }
    readMapColors();
    // Location filter state (Region / Country selects further down).
    let locRegion = "", locCountry = "";
    // Country recommended use has no switch: it is on whenever a group is ticked (see
